#!/usr/bin/env node
/**
 * build-icons.js
 * Generates public/ui/lucide-icons.js from the Lucide icon set (lucide-static, ISC),
 * with only the icons the app uses. The generated file is committed, so the app and the
 * Docker image don't need the package. To add an icon: put it in ICONS and run
 *   npm run icons
 * Browse names at https://lucide.dev/icons
 */
const fs = require('fs');
const path = require('path');

// App name -> Lucide name. App code calls icon('<app name>') (or icon('<lucide name>')).
const ICONS = {
    plus: 'plus',
    x: 'x',
    search: 'search',
    maximize: 'maximize',
    minimize: 'minimize',
    focus: 'focus',
    sun: 'sun',
    moon: 'moon',
    settings: 'settings',
    more: 'ellipsis-vertical',
    logout: 'log-out',
    terminal: 'square-terminal',
    pin: 'pin',
    copy: 'copy',
    edit: 'pencil',
    history: 'rotate-ccw-clock',
    keyboard: 'keyboard',
    user: 'user',
    folder: 'folder',
    chevronRight: 'chevron-right',
    chevronLeft: 'chevron-left',
    closeOthers: 'copy-x',
    arrowRightBar: 'arrow-right-to-line',
    restore: 'undo-2',
    gitBranch: 'git-branch',
    list: 'list',
    clock: 'clock',
    activity: 'activity',
    mic: 'mic',
    bolt: 'zap',
    clipboard: 'clipboard-paste',
    clipboardList: 'clipboard-list',
    trash: 'trash',
    globe: 'globe',
    refresh: 'rotate-cw',
    // File manager
    file: 'file',
    fileText: 'file-text',
    fileCode: 'file-code',
    fileImage: 'file-image',
    fileVideo: 'file-video-camera',
    fileAudio: 'file-music',
    fileArchive: 'file-archive',
    fileSheet: 'file-spreadsheet',
    fileJson: 'file-braces',
    fileKey: 'file-key',
    fileTerminal: 'file-terminal',
    folderOpen: 'folder-open',
    folderPlus: 'folder-plus',
    folderSymlink: 'folder-symlink',
    folderInput: 'folder-input',
    filePlus: 'file-plus',
    files: 'files',
    hardDrive: 'hard-drive',
    cloud: 'cloud',
    server: 'server',
    house: 'house',
    star: 'star',
    starOff: 'star-off',
    upload: 'upload',
    paperclip: 'paperclip',
    wrapText: 'text-wrap',
    codeXml: 'code-xml',
    lightbulb: 'lightbulb',
    triangleAlert: 'triangle-alert',
    octagonAlert: 'octagon-alert',
    messageWarning: 'message-square-warning',
    download: 'download',
    scissors: 'scissors',
    arrowUp: 'arrow-up',
    grid: 'layout-grid',
    listView: 'layout-list',
    eye: 'eye',
    eyeOff: 'eye-off',
    info: 'info',
    check: 'check',
    checkCheck: 'check-check',
    squareCheck: 'square-check',
    table: 'table',
    square: 'square',
    sort: 'arrow-up-down',
    save: 'save',
    externalLink: 'external-link',
    link: 'link',
    loader: 'loader-circle',
    panelLeft: 'panel-left',
    chevronDown: 'chevron-down',
    chevronUp: 'chevron-up',
    // Available for new buttons (use icon('monitor'), etc.)
    monitor: 'monitor',
    smartphone: 'smartphone',
    shield: 'shield-check',
    bot: 'bot',
    login: 'log-in',
    // Notes tab
    notes: 'notebook-pen',
    tag: 'tag',
    arrowLeft: 'arrow-left',
    // /admin page
    bell: 'bell',
    webhook: 'webhook',
    cloudUpload: 'cloud-upload',
    // Notes editor formatting bar
    bold: 'bold',
    italic: 'italic',
    quote: 'quote',
    listOrdered: 'list-ordered',
    code: 'code',
    minus: 'minus',
    heading: 'heading',
    gripVertical: 'grip-vertical',
    image: 'image',
    strikethrough: 'strikethrough',
    // Vibecoding: switch which agent's UI tab is shown for the open project
    swap: 'arrow-left-right',
};

const escapeAttr = value => String(value).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');

function toSvgInner(nodes) {
    return nodes.map(([tag, attrs]) => {
        const attributes = Object.entries(attrs).map(([k, v]) => `${k}="${escapeAttr(v)}"`).join(' ');
        return `<${tag} ${attributes}/>`;
    }).join('');
}

const pkgDir = path.dirname(require.resolve('lucide-static/package.json'));
const nodes = require(path.join(pkgDir, 'icon-nodes.json'));
const { version } = require(path.join(pkgDir, 'package.json'));

const out = {};
const missing = [];
for (const [alias, lucideName] of Object.entries(ICONS)) {
    const icon = nodes[lucideName];
    if (!icon) {
        missing.push(lucideName);
        continue;
    }
    const svg = toSvgInner(icon);
    out[alias] = svg;
    out[lucideName] = svg; // the official Lucide name works too
}
if (missing.length) {
    console.error(`Ícones não encontrados no Lucide ${version}: ${missing.join(', ')}`);
    process.exit(1);
}

const target = path.join(__dirname, '..', 'public', 'ui', 'lucide-icons.js');
fs.writeFileSync(target, `/**
 * lucide-icons.js - GENERATED by scripts/build-icons.js, do not edit by hand.
 * Lucide icons v${version} (https://lucide.dev), ISC License, Copyright (c) Lucide Contributors.
 */
export const LUCIDE_VERSION = '${version}';

export default ${JSON.stringify(out, null, 4)};
`);
console.log(`${Object.keys(ICONS).length} ícones do Lucide ${version} gravados em ${path.relative(process.cwd(), target)}`);
